INSERT INTO "PUBLIC"."METHOD" VALUES
(1, STRINGDECODE('-Les exigences sont bien d\u00e9finies et peu susceptibles de changer.<br/> Les projets sont simples et de courte dur\u00e9e.'), STRINGDECODE('Le mod\u00e8le en cascade est une m\u00e9thode s\u00e9quentielle dans laquelle les phases du projet\n(analyse, conception, d\u00e9veloppement, tests, d\u00e9ploiement)\nsont ex\u00e9cut\u00e9es l''une apr\u00e8s l''autre, sans retour possible en arri\u00e8re.'), STRINGDECODE('Changements fr\u00e9quents et projets complexes le client demande de la visibilit\u00e9'), 'Cascade', 1),
(2, STRINGDECODE('\n- Des tests \u00e0 chaque phase de la conception sont envisageables.<br/>\n- Des normes \u00e9lev\u00e9es de qualit\u00e9 strictes.<br/>\n- Les projets ont des exigences claires et immuables.'), STRINGDECODE('Le cycle en V est une extension du mod\u00e8le en cascade o\u00f9 chaque phase de d\u00e9veloppement\nest associ\u00e9e \u00e0 une phase de test correspondante.<br/>\n Il offre une approche plus rigide, o\u00f9 la validation et la v\u00e9rification sont effectu\u00e9es simultan\u00e9ment.'), STRINGDECODE('Les projets n\u00e9cessitent une flexibilit\u00e9 ou une adaptabilit\u00e9 \u00e0 des ajustements rapides.<br/>\nLes \u00e9quipes manquent d''expertise en mati\u00e8re de tests rigoureux.'), 'Cycle en V', 1),
(3, STRINGDECODE('\nLes projets sont complexes, de grande envergure, et comportent des risques \u00e9lev\u00e9s.<br/>\nUne analyse continue des risques et des prototypes fr\u00e9quents sont n\u00e9cessaires.'), STRINGDECODE('Le mod\u00e8le spirale est une m\u00e9thode it\u00e9rative qui combine les aspects\n du mod\u00e8le en cascade et des m\u00e9thodes agiles.<br/>\nElle met l''accent sur l''analyse des risques \u00e0 chaque it\u00e9ration, permettant ainsi une gestion proactive des risques.'), STRINGDECODE('- Les budgets et les d\u00e9lais sont tr\u00e8s limit\u00e9s.<br/>\n- Les \u00e9quipes manquent d''exp\u00e9rience en gestion des risques.<br/>\n- Le projet est de petite taille avec des exigences stables.'), 'Spirale', 1),
(4, STRINGDECODE('Les projets n\u00e9cessitent le d\u00e9veloppement parall\u00e8le de composants mat\u00e9riels et logiciels.<br/>\nUne synchronisation pr\u00e9cise entre les diff\u00e9rents aspects du projet est essentielle.\nLes \u00e9quipes ont une expertise en gestion de projets hybrides.'), STRINGDECODE('Le mod\u00e8le en Y est une m\u00e9thode hybride\nqui combine les \u00e9l\u00e9ments du cycle en V et des approches de prototypage.<br/>\nIl introduit des chemins parall\u00e8les pour le d\u00e9veloppement mat\u00e9riel et logiciel,\ntout en se rejoignant pour l''int\u00e9gration et les tests.'), STRINGDECODE('Les projets ne comportent pas d''\u00e9l\u00e9ments multidisciplinaires.<br/> Les ressources ne sont pas suffisantes pour g\u00e9rer plusieurs chemins de d\u00e9veloppement en parall\u00e8le.'), 'Cycle en Y', 1),
(5, STRINGDECODE('Les projets n\u00e9cessitent un flux de travail continu sans cycles ou sprints d\u00e9finis.<br/>\nL''objectif est d''am\u00e9liorer l''efficacit\u00e9 et la gestion des priorit\u00e9s.<br/>\nLes \u00e9quipes veulent adopter une m\u00e9thode flexible avec des changements progressifs.'), STRINGDECODE('Kanban est une m\u00e9thode agile qui se concentre sur la visualisation du flux de travail,\nla limitation du travail en cours, et l''am\u00e9lioration continue.<br/> Les t\u00e2ches sont g\u00e9r\u00e9es \u00e0 l''aide d''un tableau Kanban qui montre leur progression.'), STRINGDECODE('Les \u00e9quipes pr\u00e9f\u00e8rent une structure plus d\u00e9finie avec des r\u00f4les et des responsabilit\u00e9s claires.<br/>\nLes projets n\u00e9cessitent des d\u00e9lais fixes et des objectifs rigides.'), 'Kanban', 2),
(6, STRINGDECODE('\nLes projets ont des exigences changeantes et complexes.<br/>\nL''\u00e9quipe de d\u00e9veloppement est autonome et pluridisciplinaire.<br/>\nLe produit doit \u00eatre livr\u00e9 par incr\u00e9ments fr\u00e9quents avec des feedbacks r\u00e9guliers du client.'), STRINGDECODE('Scrum est une m\u00e9thode agile qui utilise des sprints\n(cycles de d\u00e9veloppement courts de 2 \u00e0 4 semaines)\npour livrer des incr\u00e9ments de produit.'), STRINGDECODE('\nLa d\u00e9finition du p\u00e9rim\u00e8tre n''est pas claire.<br/>\nLes projets n\u00e9cessitent des d\u00e9lais rigides et une planification pr\u00e9dictive.<br/>\nL''\u00e9quipe n''est pas familiaris\u00e9e avec la m\u00e9thodologie Scrum.<br/>\nLes parties prenantes ne sont pas disponibles pour des retours fr\u00e9quents.'), 'Scrum', 2),
(7, STRINGDECODE('Les projets n\u00e9cessitent une qualit\u00e9 de code \u00e9lev\u00e9e et des livraisons fr\u00e9quentes.<br/>\nLes exigences sont susceptibles de changer rapidement.<br/>\nLes \u00e9quipes de d\u00e9veloppement sont petites et tr\u00e8s collaboratives.'), STRINGDECODE('Extreme Programming (XP) est une m\u00e9thode agile\n qui met l''accent sur les meilleures pratiques de d\u00e9veloppement logiciel\ncomme les tests unitaires, la programmation en bin\u00f4me, l''int\u00e9gration continue,\n et la r\u00e9vision de code fr\u00e9quente.'), STRINGDECODE('L''\u00e9quipe manque d''exp\u00e9rience ou de discipline dans les pratiques d''ing\u00e9nierie avanc\u00e9es.<br/>\nLe projet a des exigences tr\u00e8s rigides et peu susceptibles de changer.'), 'XP', 2),
(8, STRINGDECODE('Les \u00e9quipes veulent la structure de Scrum avec la flexibilit\u00e9 de Kanban.<br/>\nLes projets n\u00e9cessitent des livraisons continues tout en maintenant la gestion des priorit\u00e9s.<br/>\nL''objectif est d''am\u00e9liorer progressivement les processus tout en conservant certaines pratiques de Scrum.'), STRINGDECODE('Scrumban combine les pratiques de Scrum et de Kanban.<br/>\nIl conserve la structure de Scrum (r\u00f4les, sprints, r\u00e9trospectives) tout en adoptant la flexibilit\u00e9 de Kanban\n(flux de travail continu, gestion du travail en cours).'), STRINGDECODE('Les \u00e9quipes pr\u00e9f\u00e8rent une approche purement Scrum ou Kanban.<br/>\nLes projets n\u00e9cessitent une approche rigide et tr\u00e8s structur\u00e9e.'), 'Scrumban', 2),
(9, STRINGDECODE('L''organisation cherche \u00e0 optimiser ses processus et r\u00e9duire les gaspillages.<br/>\nLes projets n\u00e9cessitent des cycles de livraison courts avec une focalisation sur la valeur.'), STRINGDECODE('Lean est une approche de gestion de projet visant \u00e0 maximiser la valeur tout en minimisant le gaspillage.<br/>\nIl se concentre sur l''efficacit\u00e9, l''am\u00e9lioration continue, et la livraison rapide de valeur au client.'), STRINGDECODE('Les \u00e9quipes ont besoin de directives et de structures rigides.<br/>\nL''organisation n''a pas de culture d''am\u00e9lioration continue.<br/>\nLes processus actuels sont d\u00e9j\u00e0 tr\u00e8s optimis\u00e9s.'), 'Lean', 2),
(10, STRINGDECODE('L''organisation veut une approche hybride qui combine plusieurs pratiques.<br/>\nLes \u00e9quipes ont besoin de lignes directrices pour des pratiques d''agilit\u00e9 d''entreprise.<br/>\nLe projet est de grande envergure et n\u00e9cessite une approche adaptable.'), STRINGDECODE('Disciplined Agile Delivery (DAD) est un cadre de gestion de projet agile qui fournit des lignes directrices pour des \u00e9quipes qui \u00e9voluent,\n combinant des pratiques d''Agile, Lean, et autres approches.<br/>\nIl couvre toutes les \u00e9tapes de d\u00e9veloppement, de l''initialisation au d\u00e9ploiement.'), STRINGDECODE('Les projets sont petits et ne n\u00e9cessitent pas de pratiques agiles d''entreprise.<br/>\nLes \u00e9quipes pr\u00e9f\u00e8rent des cadres plus simples comme Scrum ou Kanban.<br/>\nL''organisation a des contraintes rigides et pr\u00e9f\u00e8re une approche unique.'), 'Dad', 2),
(11, STRINGDECODE('L''organisation a plusieurs \u00e9quipes de d\u00e9veloppement n\u00e9cessitant une synchronisation.<br/>\nLes projets sont de grande envergure, avec des d\u00e9pendances complexes.<br/>\nL''entreprise souhaite aligner l''agilit\u00e9 de l''\u00e9quipe avec des objectifs d''entreprise plus larges.'), STRINGDECODE('Scaled Agile Framework (SAFe) est un cadre qui permet de mettre \u00e0 l''\u00e9chelle les pratiques agiles pour de grandes entreprises.<br/>\n Il fournit une structure pour aligner le d\u00e9veloppement \u00e0 grande \u00e9chelle avec les objectifs strat\u00e9giques de l''entreprise.'), STRINGDECODE('Les \u00e9quipes ou les projets sont petits et ne n\u00e9cessitent pas de mise \u00e0 l''\u00e9chelle.<br/>\nL''organisation pr\u00e9f\u00e8re des approches moins formelles.'), 'Safe', 2),
(12, STRINGDECODE('L''organisation utilise d\u00e9j\u00e0 Scrum et souhaite l''\u00e9tendre \u00e0 plusieurs \u00e9quipes.<br/>\nLe projet est complexe et n\u00e9cessite une collaboration inter-\u00e9quipes.<br/> L''entreprise souhaite minimiser la bureaucratie tout en mettant \u00e0 l''\u00e9chelle.'), STRINGDECODE('Large-Scale Scrum (LeSS) est une extension de Scrum pour les grandes \u00e9quipes de d\u00e9veloppement.<br/>\n Il conserve les principes de base de Scrum tout en les adaptant \u00e0 une \u00e9chelle plus grande,\n avec plusieurs \u00e9quipes travaillant sur le m\u00eame produit.'), STRINGDECODE('Les \u00e9quipes n''ont pas d''exp\u00e9rience avec Scrum.<br/>\nL''organisation a des exigences rigides de processus et de documentation.<br/>\nLes projets ne sont pas assez grands pour justifier la mise \u00e0 l''\u00e9chelle.'), 'Less', 2),
(13, STRINGDECODE('Les \u00e9quipes Scrum doivent collaborer sur des produits complexes.<br/>\nL''accent est mis sur l''int\u00e9gration continue et la gestion des d\u00e9pendances.<br/>\nL''organisation veut utiliser un cadre qui reste proche des principes de Scrum.'), STRINGDECODE('Nexus est un cadre de mise \u00e0 l''\u00e9chelle de Scrum con\u00e7u pour des \u00e9quipes\n qui travaillent ensemble sur un produit unique.<br/> Il se concentre sur la gestion des d\u00e9pendances et l''int\u00e9gration continue.'), STRINGDECODE('Les \u00e9quipes ne sont pas familiaris\u00e9es avec Scrum.<br/>\nLe projet est simple et n''a pas besoin de mise \u00e0 l''\u00e9chelle.<br/>\nLes \u00e9quipes pr\u00e9f\u00e8rent des approches plus l\u00e9g\u00e8res comme LeSS.'), 'Nexus', 2),
(14, STRINGDECODE('Plusieurs \u00e9quipes Scrum doivent travailler en parall\u00e8le et coordonner leurs efforts.<br/>\nL''objectif est de g\u00e9rer les interd\u00e9pendances tout en utilisant les principes Scrum.'), STRINGDECODE('Scrum of Scrums est une technique de coordination utilis\u00e9e pour mettre \u00e0 l''\u00e9chelle Scrum dans les grandes organisations.<br/>\n Des repr\u00e9sentants de chaque \u00e9quipe Scrum se rencontrent r\u00e9guli\u00e8rement pour coordonner le travail.'), STRINGDECODE('Les \u00e9quipes ne sont pas autonomes ou ne ma\u00eetrisent pas bien Scrum.<br/>\nLe projet est petit ou n''implique qu''une seule \u00e9quipe.<br/>\nIl n''y a pas de besoins de coordination fr\u00e9quente.'), 'Scrum of Scrums', 2),
(15, STRINGDECODE('L''organisation veut encourager une culture d''autonomie et d''innovation.<br/>\nL''accent est mis sur la flexibilit\u00e9 organisationnelle et la collaboration.<br/>\nLes \u00e9quipes pr\u00e9f\u00e8rent travailler de mani\u00e8re autonome tout en maintenant une synchronisation.'), STRINGDECODE('Le mod\u00e8le Spotify est une approche de gestion d''\u00e9quipe agile, mettant l''accent sur la culture et la structure d''\u00e9quipe autonome.<br/>\nIl vise \u00e0 maximiser l''alignement et l''autonomie.'), STRINGDECODE('L''organisation n\u00e9cessite des contr\u00f4les stricts et une hi\u00e9rarchie rigide.<br/>\nLes \u00e9quipes n''ont pas l''exp\u00e9rience n\u00e9cessaire pour g\u00e9rer leur autonomie.<br/>\nLes projets ont des exigences formelles de documentation et de processus.'), 'Spotify', 2),
(16, STRINGDECODE('L''organisation veut appliquer des principes agiles au niveau de l''entreprise, pas seulement au d\u00e9veloppement.<br/>\nLes \u00e9quipes veulent un cadre flexible mais structur\u00e9 pour diff\u00e9rents d\u00e9partements.<br/>\nL''objectif est d''aligner l''ensemble de l''organisation avec une culture agile.'), STRINGDECODE('Enterprise Scrum est une m\u00e9thode d''\u00e9chelle agile qui permet l''application de Scrum\ndans divers contextes organisationnels (marketing, vente, etc.),\npas seulement pour le d\u00e9veloppement logiciel.'), STRINGDECODE('L''entreprise n''a pas de culture d''innovation ou de flexibilit\u00e9.<br/>\nLes \u00e9quipes ne ma\u00eetrisent pas les concepts de base de Scrum.<br/>\nLes projets sont d\u00e9j\u00e0 bien g\u00e9r\u00e9s avec d''autres cadres d''agilit\u00e9 \u00e0 l''\u00e9chelle.'), 'Enterprise Scrum (ES)', 2)